CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE departments (id UUID PRIMARY KEY, name VARCHAR(120) UNIQUE NOT NULL, categories VARCHAR(500) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE official_assignments (id UUID PRIMARY KEY, official_id UUID NOT NULL REFERENCES users(id), department_id UUID NOT NULL REFERENCES departments(id), ward VARCHAR(80), active BOOLEAN NOT NULL DEFAULT true, UNIQUE(official_id,department_id));
CREATE TABLE complaints (id UUID PRIMARY KEY, citizen_id UUID NOT NULL REFERENCES users(id), department_id UUID REFERENCES departments(id), assigned_official_id UUID REFERENCES users(id), title VARCHAR(160) NOT NULL, description TEXT NOT NULL, category VARCHAR(40) NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', location VARCHAR(255) NOT NULL, ward VARCHAR(80), status VARCHAR(20) NOT NULL, assignment_status VARCHAR(30) NOT NULL, sla_deadline TIMESTAMPTZ NOT NULL, overdue BOOLEAN NOT NULL DEFAULT false, resolution_notes TEXT, ai_status VARCHAR(30) NOT NULL DEFAULT 'NOT_REQUESTED', ai_summary TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_complaints_citizen ON complaints(citizen_id); CREATE INDEX idx_complaints_department ON complaints(department_id); CREATE INDEX idx_complaints_deadline ON complaints(sla_deadline);
CREATE TABLE complaint_status_history (id UUID PRIMARY KEY, complaint_id UUID NOT NULL REFERENCES complaints(id) ON DELETE CASCADE, from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, note TEXT, actor_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), message TEXT NOT NULL, read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
